with flattened as (select id, service, host, log_ts, level, latency_ms, key, value from app_logs lateral view outer explode(context) x as key, value) select date_trunc('hour', log_ts) as hour_window, date_trunc('day', log_ts) as activity_day, round(avg(latency_ms), 2) as avg_latency_ms, avg(latency_ms) filter (where host = 'h1') as h1_avg_latency_ms, sort_array(collect_set(level)) as level_list, stddev_samp(latency_ms) as latency_ms_stddev, count(distinct host) as distinct_hosts, count(*) filter (where level = 'INFO') as info_rows from flattened group by hour_window, activity_day
